import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test.describe("vendor search", () => {
  test("search ignores case and matches part of a name", { tag: "@LIF-13" }, async ({ apiAs, factory }) => {
    // Arrange
    const member = await apiAs("member");
    const vendor = await factory.vendor({ as: "member", name: uniqueName("Zephyrine Cold Storage") });

    // Act
    const response = await member.get("/api/vendors", { params: { q: "COLD stor" } });

    // Assert
    const page = await expectStatus<{ items: { id: string; name: string }[]; total: number }>(response, 200);
    expect(page.items.map((v) => v.id)).toContain(vendor.id);
    expect(page.items.find((v) => v.id === vendor.id)?.name).toBe(vendor.name);
  });
});
